import java.nio.file.*;
import java.util.*;

/** Behavior and migration checks for the roadmap implementation. */
public final class RoadmapChecks {
    private static void check(boolean b,String message){if(!b)throw new AssertionError(message);}
    public static void run(){try{
        WorldConfig c=WorldConfig.preset("Selection exploration");c.generationSeconds=1;
        Simulation s=new Simulation(c,1234);for(int i=0;i<60;i++)s.step();check(s.awaitingSelection&&s.selectionRound==1,"Hold completed population before breeding");long t=s.elapsedTicks,b=s.totalBirths;byte[] held=WorldIO.encode(s);for(int i=0;i<100;i++)s.step();check(t==s.elapsedTicks&&b==s.totalBirths&&Arrays.equals(held,WorldIO.encode(s)),"Held generation consumes no time or RNG");
        long naturalBefore=s.stats(Simulation.Species.PREY).deaths;var winner=s.bestCandidate(Simulation.Species.PREY).genome();s=WorldIO.decode(held);s.evolve();check(!s.awaitingSelection&&s.selectionRound==2&&s.completedLeaders.size()==2,"Explicit breeding releases hold and records champions");check(Arrays.equals(winner.weights(),s.creatures.get(0).weights),"Inspection preserves elite genome");check(s.stats(Simulation.Species.PREY).replacements>0&&s.stats(Simulation.Species.PREY).deaths==naturalBefore,"Replacement is administrative, not natural death");
        s=new Simulation(new WorldConfig(),42);var hunter=s.creatures.stream().filter(x->x.species==Simulation.Species.PREDATOR).findFirst().orElseThrow();s.creatures.clear();s.creatures.add(hunter);s.food.clear();hunter.age=500;hunter.energy=hunter.capacity()*.98;hunter.x=hunter.y=100;hunter.weights=new double[Simulation.WEIGHT_COUNT];s.step();check(s.eggs.size()==1,"Hunter egg fixture");long losses=s.totalEggLoss;s.setPredators(false);check(s.eggs.isEmpty()&&s.totalEggLoss==losses+1&&s.stats(Simulation.Species.PREDATOR).eggLosses==1,"Hunter removal accounts for eggs");check(s.stats(Simulation.Species.PREDATOR).removals==1&&s.stats(Simulation.Species.PREDATOR).deaths==0,"Administrative removal remains separate");
        WorldConfig wide=WorldConfig.preset("Steady observation").scaledDensity(1.5);s=new Simulation(wide,556);check(s.width()==1800&&s.height()==1275&&s.count(Simulation.Species.PREY)==135,"Scaled dimensions and founder density");for(int i=0;i<600;i++)s.step();Simulation copy=WorldIO.decode(WorldIO.encode(s));for(int i=0;i<120;i++){s.step();copy.step();}check(Arrays.equals(WorldIO.encode(s),WorldIO.encode(copy)),"Custom worlds resume exactly");
        c=new WorldConfig();c.width=2;boolean rejected=false;try{c.validate();}catch(IllegalArgumentException e){rejected=true;}check(rejected,"Reject invalid settings");
        c=WorldConfig.preset("Supported coexistence");s=new Simulation(c,55);check(s.sources.size()==16,"Supported habitat has sixteen sources");
        WorldConfig serial=WorldConfig.preset("Steady observation");var a=new Simulation(serial,809);var z=new Simulation(serial,809);check(Arrays.equals(WorldIO.encode(a),WorldIO.encode(z)),"Seeds reproduce identities and state");check(!a.creatures.get(0).name.isBlank()&&a.creatures.get(0).clan.endsWith(" Clan"),"Named identity");
        Simulation legacy=WorldIO.read(Path.of("tests/fixtures/legacy-v1.snapshot"));check(legacy.statisticsSinceMigration&&!legacy.seedKnown&&legacy.history.stream().noneMatch(Simulation.Sample::roleMetricsAvailable),"Legacy save marks unavailable historical data");for(int i=0;i<900;i++)legacy.step();check(digest(legacy).equals(Files.readString(Path.of("tests/fixtures/legacy-after-900.txt"))),"Legacy biological continuation matches original baseline");
        var cfg=new ExperimentRunner.Config(ExperimentRunner.Variable.FOOD_ABUNDANCE,55,55,2,3,701,new WorldConfig(),2,null,1,2);var parallel=ExperimentRunner.run(cfg,()->false,p->{});var serialResult=ExperimentRunner.run(new ExperimentRunner.Config(cfg.variable(),55,55,2,3,701,new WorldConfig(),1,null,1,2),()->false,p->{});check(parallel.csv().equals(serialResult.csv()),"Parallel paired results equal serial results");
        Path folder=Files.createTempDirectory("primordial-batch-");EnumMap<Simulation.Species,List<Simulation.Genome>> pools=new EnumMap<>(Simulation.Species.class);var source=new Simulation(new WorldConfig(),77);for(var role:Simulation.Species.values())pools.put(role,source.topGenomes(role));
        try(WorldBatch batch=new WorldBatch(new WorldConfig(),pools,8801,2,2,2,1,1,folder,"Regression top pools")){long deadline=System.nanoTime()+30_000_000_000L;while(batch.busy()&&System.nanoTime()<deadline)Thread.sleep(20);check(!batch.busy(),"Batch finishes");for(var status:batch.statuses()){check(status.state().equals("Complete"),"Batch completion: "+status.detail());Simulation checkpoint=WorldIO.read(status.checkpoint());check(checkpoint.elapsedTicks==120,"Checkpoint is at final tick");check(Files.readString(status.checkpoint().getParent().resolve("observations.csv")).contains("descendant_births"),"Incremental evidence recorded");check(checkpoint.founders.values().stream().allMatch(g->pools.get(g.species()).stream().anyMatch(parent->Arrays.equals(parent.weights(),g.weights()))),"Each island starts from captured parent pools");}}
        c=new WorldConfig();c.resourceLifetime=.1;c.seasons=false;c.abundance=0;s=new Simulation(c,90);Simulation.Food old=new Simulation.Food(100,100,2);old.age=100;s.food.add(old);s.step();check(!s.food.contains(old),"Optional resource turnover");
        WorldConfig inspection=WorldConfig.preset("Selection exploration");inspection.generationSeconds=1;
        try(WorldBatch batch=new WorldBatch(inspection,pools,9001,1,1,3,1,1,folder.resolve("inspection"),"Paused regression")){waitFor(batch);check(batch.statuses().get(0).state().equals("Inspect generation"),"Island releases worker at a generation boundary");batch.resume(1);waitFor(batch);Simulation resumed=WorldIO.read(batch.statuses().get(0).checkpoint());check(resumed.selectionRound==2&&resumed.awaitingSelection&&resumed.elapsedTicks==120,"Island resumes its exact held generation");}
        SpatialGrid<Integer> grid=new SpatialGrid<>();List<double[]> positions=new ArrayList<>();Random random=new Random(17);for(int i=0;i<300;i++){double x=random.nextDouble()*2400,y=random.nextDouble()*1700;positions.add(new double[]{x,y});grid.add(i,x,y);}for(int k=0;k<30;k++){double x=random.nextDouble()*2400,y=random.nextDouble()*1700,radius=360;List<Integer> expected=new ArrayList<>();for(int i=0;i<positions.size();i++){double[] xy=positions.get(i);if((xy[0]-x)*(xy[0]-x)+(xy[1]-y)*(xy[1]-y)<=radius*radius)expected.add(i);}check(grid.near(x,y,radius).equals(expected),"Local query preserves brute-force candidates and encounter order");}
        var focal=source.creatures.get(0).genome();var pair=new EvolutionStudyPanel.Pair("Reference",focal,focal);String current=EvolutionStudyPanel.evaluate(pair,false,false,99001,120,new WorldConfig(),()->false),ancestor=EvolutionStudyPanel.evaluate(pair,true,false,99001,120,new WorldConfig(),()->false);check(current.replace(",descendant,",",founder,").equals(ancestor),"Identical reproductive study genomes match on held-out seeds");
        javax.swing.SwingUtilities.invokeAndWait(()->{WorldConfig configuration=WorldConfig.preset("Steady observation");WorldSettingsPanel form=new WorldSettingsPanel(configuration,123);check(form.value().properties().equals(configuration.properties())&&form.seed()==123,"Advanced editors preserve complete settings");Main app=new Main(false);check(!app.sim.predatorsEnabled&&!app.predatorControl.isSelected(),"App and controls agree on held-out-tested starting preset");app.modeControl.setSelectedIndex(1);app.sim.config.generationSeconds=1;app.inspectGeneration.doClick();for(int i=0;i<60;i++)app.sim.step();app.refresh();check(app.sim.awaitingSelection&&app.next.getText().equals("Breed & continue")&&!app.pause.isEnabled(),"UI exposes generation inspection before replacement");app.next.doClick();check(app.sim.selectionRound==2&&!app.sim.awaitingSelection,"Breed & continue releases the held world");check(app.metric.getItemCount()==11,"Per-role graphs available");String[] csv=app.historyCsv().split("\n");check(csv[0].split(",").length==15&&csv[1].split(",").length==15,"History export includes per-role measures");app.timer.stop();});
        Path preset=folder.resolve("replay.settings");serial.write(preset,123456);check(WorldConfig.read(preset).properties().equals(serial.properties())&&WorldConfig.readSeed(preset)==123456L,"Settings files preserve a replay seed");
        System.out.println("PASS: advanced configuration, named identities, generation holds, role accounting, legacy saves, scaled worlds, parallel replay, checkpoints and source pools.");
    }catch(Exception e){throw new AssertionError("Roadmap checks",e);}}
    private static String digest(Simulation s){StringBuilder b=new StringBuilder();b.append(s.tick).append(':').append(s.totalBirths).append(':').append(s.totalDeaths).append(':').append(s.totalEnergySpent);for(var c:s.creatures)b.append('|').append(c.id).append(':').append(c.x).append(':').append(c.y).append(':').append(c.energy).append(':').append(Arrays.toString(c.weights));for(var f:s.food)b.append('|').append(f.x).append(':').append(f.y).append(':').append(f.angle);return b.toString();}
    private static void waitFor(WorldBatch batch)throws InterruptedException{long until=System.nanoTime()+30_000_000_000L;while(batch.busy()&&System.nanoTime()<until)Thread.sleep(20);check(!batch.busy(),"Background world responds within test deadline");check(!batch.statuses().get(0).state().equals("Failed"),batch.statuses().get(0).detail());}
    private RoadmapChecks(){}
}
